import { Tooltip } from '@arco-design/web-react';
import { useEffect, useState } from 'react';
import { ApiFindParam } from '..';
import { JSONSchemaCustom } from '../..';
import SchemaTable, { SchemaTableProps } from '../../Table';


const logSchema: JSONSchemaCustom = {
    type: "object",
    "properties": {
        "id": {
            type: "string",
            "title": "日志id",
            "columnProps": {
                "ellipsis": true
            }
        },
        "updatedAt": {
            "type": "string",
            title: "修改时间"
        },
        "userId": {
            "type": "string",
            "title": "修改人"
        },
        "field": {
            "type": "string",
            "title": "修改字段",
            "columnProps": {
                "ellipsis": true
            }
        },
        "description": {
            "type": "string",
            "title": "修改说明",
            columnProps: {
                ellipsis: true,
                render: (str) => (
                    <Tooltip content={str || "用户触发修改"} position="tl">
                        {str || "用户触发修改"}
                    </Tooltip>
                )
            }
        }
    }
}

export interface LogProps extends Partial<SchemaTableProps> {
    // 查询参数
    params?: any;
    getTableData?: (param: ApiFindParam) => Promise<{ list: any[], total?: number }>,
}
export default ({ getTableData, params, ...props  }: LogProps) => {

    const [pagination, setPagination] = useState({
        page: 1,
        size: 10,
        total: 0, 
    });
    const [data, setData] = useState<any[]>([]);
    const [loading, setLoading] = useState<boolean>(false);

    const resetPagination = () => {
        let pagin = { page: 1, size: 10, total: 0, }
        setPagination(pagin)
        return pagin;
    }

    const updatePagination = (params: any) => {
        const pagin = { ...pagination, ...params };
        setPagination({
            ...pagination,
            ...params
        })
        return pagin;
    }

    const getList = (pagin: any) => {
        setLoading(true);
        getTableData({
            "current": pagin.page,
            "pageSize": pagin.size,
        }).then((res) => {
            setData(res.list);
            pagin.total = res.total;
            setPagination(pagin);
        }).finally(() => {
            setLoading(false);
        });
    }


    useEffect(() => {
        if(getTableData){
            const pagin = resetPagination();
            getList(pagin);
        }
    },[params])

    return (
        <SchemaTable 
            schema={logSchema}
            loading={loading}
            rowKey="id"
            pagination={{
                sizeCanChange: true,
                showTotal: true,
                current: pagination.page,
                pageSize: pagination.size,
                total: pagination.total,
                onChange: (page,size) => {
                    const pagin = updatePagination({
                        page,
                        size
                    })
                    if(getTableData){
                        getList(pagin);
                    }
                }
            }}
            data={data}
            {...props}
        />
    )
}