import { isVerifySync } from "@/environments/utils/verify";
import { schemaToAllData, schemaToList } from "@/utils/schema";
import i18next from "i18next";

/**
 * 将JSONSchema 转为 Descriptions-data 列表
 * @param schema 
 * @returns 
 */
export const schemaToDescriptionsData = (schema: JSONSchema, data: Record<string, any> = {}) => {
    const { children: list = [] } = schemaToList(schema);
  
    const objData = schemaToAllData(schema, data);
    return list.filter((o) => {
        if(!o._store.show) return true;
        return isVerifySync(o._store.show, data);
    }).map((o) => {
      const { _store, key } = o;
      const { title, type, enum: enumList, format, fieldProps, default: defaultValue, colProps = {} } = _store;
  
      const getValue = () => {
        if(format == "i18n" && fieldProps.value){
          return i18next.t('notnull.a.b.c.d.e.f.d', fieldProps.value, objData);
        }
        if(enumList){
            const item = enumList.find((o) => o.value == data[key]);
            if(item) return item.label;
        }
        return data[key] || defaultValue;
      }
  
      return {
        key,
        label: title || key,
        value: getValue(),
        format: format,
        span: colProps.span,
      }
    })
  }
  